"""gen_sprites.py: build decode/data/SPRITES.md from decode/data/sprites_index.tsv (written by render_all.py) plus the
hand-written descriptions below (what the rendered PNGs show; 'eyeballed' = this lane looked at the render)."""
import csv,os
rows=list(csv.reader(open('decode/data/sprites_index.tsv'),delimiter='\t'))
# family -> (content description, loader evidence)
FAM=[
 ('BIGSH-','encounter creature/alien portrait 88x56 (.EGA 16-colour, .BAS 4-colour) **plus its animation frames** at fixed DIM slots (found by verify on PLBATTLE; previously mis-read as stale memory): .BAS slots at file offsets 7/1273/2509/3745/4981 = full 88x56 frames 0..4 (PLBATTLE PortraitCGA + PortFrame1..4, DS 0x942E/0x9920/0x9DF4/0xA2C8/0xA79C; 3 to 5 frames per file depending on the BSAVE length); .EGA slots at 7/2727/3721/4485 = portrait + up to 3 small overlay arrays (PortraitEGA + PortEgaFrame1..3, DS 0x8052/0x8AF2/0x8ED4/0x91D0; BIGSH-5.EGA slot 2 is overrun by its 61x39 frame 1 and unused). Between the portrait and frame 1 the words are the frame script (type, delay/100) read by PLBATTLE 9B5B/9D53. Eyeballed: BIGSH-1 = green lizard-like alien holding a bone in a brown cave (EGA overlays = its head/mouth frames) / cyan-magenta version (CGA); BIGSH-3.EGA = pink insectoid creature; BIGSH-6.BAS = a saucer-shaped creature over 5 frames, the last firing a magenta beam','PLBATTLE: literals 0xC72E/0xC738 "BIGSH" + number + 0xBF8E ".EGA" / 0xBF96 ".BAS"; BLOAD .BAS to &H942E (01990, with Drive$) or .EGA to &H8052 (019BD, no Drive$) chosen by UseEGA! <> 0 (01957); portrait PUT (8,25); frames PUT 9CE4..9D2F (CGA, every 0.123 s) / 9F34..9F72 (EGA, XOR at the script offsets)'),
 ('DEMOSH','6 frames of 88x56 (CGA), file len 7416 = 6 x 1236 exactly. Eyeballed frame 0: a human soldier figure (cyan/white) pointing. Not referenced by any of the 7 game modules','DEMO.EXE only (BSAVE seg 0652 = DEMO.EXE data area); not used by the game'),
 ('ENSHP-','8 frames of 24x24 (CGA), len 1184 = 8 x 148 exactly: one enemy ship type per file, 8 rotation headings. Eyeballed ENSHP-1: small ship rotating through 8 directions','SPBATTLE: literal 0x8BE0 "ENSHP" + 0xA6B8 "-" + n + 0x8BEA ".BAS"'),
 ('SHIP-','8 frames of 24x24 (CGA), len 1184 = 8 x 148: player ship class n, 8 rotation headings. Eyeballed SHIP-1','SPACE: 0xA960 "SHIP" + 0xAA12 "-" + n + 0xA96C ".BAS"; SPBATTLE: 0x70AE "SHIP" + "-" + ".BAS"'),
 ('SHIPPICS','4 pictures 24x24 (CGA) at 150-byte slots (7, 157, 307, 457: the DIM stride is 75 integers, 2 bytes unused per slot). Eyeballed: four ship silhouettes (ship classes for the shipyard)','STARPORT: literal 0xA4C4 "SHIPPICS.BAS" (BLOAD to 0x4F9E, listing ~0xC0)'),
 ('FIRE','15 arrays (CGA): explosion animation, frames grow 8x9, 53x29, 65x45, 75x72, 55x80, 45x54, 80x80, 80x79, 80x80, 80x73, 80x74, 55x75, 55x72, 50x73, 51x74; packed back to back on even offsets. Eyeballed: bursts of white/cyan/magenta sparks, last frames show a falling ship/structure','STARPORT: literal 0xC46E "fire" (BLOAD to 0x65AE, listing ~0xA92x; ".BAS" appended by the runtime)'),
 ('GAL.','one 98x98 picture (CGA). Eyeballed: spiral galaxy of coloured dots with a small white triangle marker top-right. No module literal names "GAL" (SPACE has only GALMAP/GALAXY)','**unreferenced** by the 7 modules (DEMO.EXE or leftover)'),
 ('GALMAP','one 128x128 picture (CGA). Eyeballed: galaxy map with axes labelled 1 8 16 24 32 on both sides = 32x32 sector grid (matches GALAXY.BAS 1024 ints and the MISSION sector coordinates)','SPACE: literal 0xA828 "GALMAP.BAS" (BLOAD to 0x6E56, listing 0x1FE..0x20E)'),
 ('INMAP-','one 185x185 picture (CGA) per file: interior map of location n (7 locations = MES-1..7 descriptions, IN-1..7 cell arrays). Eyeballed INMAP-1: cyan field with white rooms; INMAP-4: a black/white maze. len 8700 vs needed 8699 (+1 pad)','INSIDE: literal 0x956C/0x9576 "INMAP" + 0x9362 "-" + n + 0x9564 ".BAS"'),
 ('INMAP.','one 186x162 picture (CGA). Eyeballed: ship/station deck plan (cyan background, black rooms with white furniture)','INSIDE: "INMAP" + ".BAS" (second INMAP literal)'),
 ('INSH','INSIDE map sprites (CGA) after 64 passability words (file offsets 7..0x86, int16, DATA_FILES.md): 0-63 the 64 5x5 map tiles (Tile0..63, 14-byte arrays from offset 0x87 = DS 0x8356), 64 the 26x24 command-panel cursor (DS 0x86D6), 65 BlipV 7x6 motion-detector blip (DS 0x8782), 66 BlipH 7x6 radiation-detector blip (DS 0x8792); the arrays end exactly at the trailer. Eyeballed: wall, corner and door-shaped map tiles, the four-way arrow cursor, two coloured blips','INSIDE: literal "INSH.BAS" (BLOAD &H82D6, listing 000B3); PUT: tiles by SUB_1CEA (01D66..02404, PSET at (x*5+8, y*5+7)), Tile42 = squad marker (XOR, 06110/06165), Cursor (280,144) XOR (0250A), BlipV (05966/05978), BlipH (0584A/0585C)'),
 ('LOGO','"STAR COMMAND" logo. LOGO.BAS = 81x19 CGA (magenta block letters); LOGO.EGA = 80x10 EGA (red/green small font). Eyeballed both','every module: "LOGO" literal (STARTUP 0xD344, SPACE 0xAA24, STARPORT 0xA65A, INSIDE 0x87E2, PLBATTLE 0xC0DC, SPBATTLE 0x714C; BLOAD to 0x40F4 = COMMON end) and PLBATTLE 0xBE7C "LOGO.EGA"'),
 ('MAP-','one 128x128 picture (CGA): sector star field n (1..16). Eyeballed MAP-1: sparse dots. MAP-2, MAP-12, MAP-15 are **4 bytes short** (BSAVE len 4096, seg 356D:1856 instead of 0B70:27xx): the last row\'s last 4 bytes are whatever is in memory when PUT','SPACE: literal 0xAEC8 "MAP" + 0xAA12 "-" + n + 0xA96C ".BAS"'),
 ('PLBTSH','18 ground-combat sprites in fixed slots (same offsets in .BAS and .EGA, slot size = EGA array size): 0-2 16x16 soldier figures (stand/walk), 3-7 24x24 blob/beast shapes, 8 26x24 move-arrows cursor, 9 1x1, 10 3x3, 11 4x4 shot dots, 12-14 24x24 explosion frames, 15-17 16x16 creature, serpent, toothed mouth. Eyeballed both files','PLBATTLE: literals 0xC742 "PLBTSH.EGA" and 0xC750 "plbtsh.bas" (BLOAD to 0xAC70, listing ~0x19C0..0x19FB, chosen by adapter)'),
 ('SPACESH','58 arrays (CGA), the SPACE screen furniture: 0-4 five 92x7 header labels (GALAXY SCAN, LONG RANGE, SECTOR SCAN, SYSTEM SCAN, VISUAL), 5-10 4x5 digits 1-6, 11-14 8x8 icons, 15 26x24 cursor arrows, 16 16x16 box, 17-19 24x24 scan blobs, 20 104x104 star-field viewport, 21 28x6, 22-24 52x19/52x32/36x32 ship and station side views, 25 24x24, 26 16x13, 27 12x10 small craft, 28-37 ten 20x20 planets, 38-47 ten 16x16 planets, 48-57 ten 8x8 planets. Eyeballed','SPACE: literal 0xA844 "SPACESH.BAS" (BLOAD to 0x4890); SPBATTLE: 0x6F92 "spacesh" (BLOAD to 0x4890)'),
 ('SPBTSH','25 arrays (CGA), space-battle sprites: 0-4 5x5 letters A-E, 5-6 3x3 "+" and "*", 7-14 eight 40x40 explosion frames, 15 24x24, 16-18 40x40, 19-21 24x24 planets, 22-24 16x16. Eyeballed','SPBATTLE: literal 0x886E "SPBTSH.BAS" (BLOAD to 0x73A0)'),
 ('SPPIC-','one 80x80 picture (CGA): starport/station view n (1..3). Eyeballed SPPIC-1: saucer-shaped station with spire','SPACE: 0xAFF0 "SPPIC" + "-" + n + ".BAS"; STARPORT: 0xA9E4 "SPPIC" + 0xA63C "-" + n + 0xA9EE ".BAS"'),
 ('SPSTGRPH','one 80x80 picture (CGA). Eyeballed: winged starport/station graphic','SPACE: literal 0xB07E "SPSTGRPH" (BLOAD to 0x9008)'),
 ('TITLE','5 arrays (CGA, SCREEN 1). 0 = 320x200 full-screen title picture "STAR COMMAND / By Winston Douglas Wood And Eric Liebenauer" with an alien, a soldier and a pillar (16004 bytes). 1-4 = attract-loop animation frames packed back to back right after it (found by lane mod-startup; previously mis-read as stale memory): 1 = 200x102 at DS 0x87E8 (5104 B), 2 = 188x98 at DS 0x9BD8 (4610 B), 3 = 184x98 at DS 0xADDA (4512 B), 4 = 184x108 at DS 0xBF7A (4972 B); DS address = 0x4964 + (file offset - 7), and the last frame ends at file offset 35209 = BSAVE len 35202 exactly, so nothing in the file is stale. Eyeballed: the alien and the soldier fighting (1 alien winds up a punch, 2 the punch reaches the soldier, 3 the soldier raises a magenta hand weapon, 4 a magenta beam/whip strikes the alien), each drawn over the matching part of picture 0','STARTUP: literal 0xD2E6 "title" (BLOAD to 0x4964, listing 0xAD..0xB9; PUT (0,0) verb 4 = XOR at 0xC4..0xCD). Frames: listing 0x6C5..0x6D8 `coord (28,54); bx=0x87E8; dl=3; RT3E_58` = PUT (28,54),Frame1,PSET; 0x6EB..0x6FE PUT (48,58),Frame2,PSET (bx=0x9BD8); 0x711..0x724 PUT (48,58),Frame3,PSET (bx=0xADDA); 0x737..0x74A PUT (44,48),Frame4,PSET (bx=0xBF7A); 0x796..0x7A7 PUT (0,0),picture,PSET restores (decode/pseudo/STARTUP.bas.md L_06C5..L_0796)'),
 ('TR-','4 terrain tiles 16x16 per file, slots of 132 bytes in both .EGA (16x16 EGA = 132 bytes) and .BAS (CGA 68 bytes + 64 unused). Eyeballed TR-1 (rock/plant/water tiles), TR-3.EGA (grass, mushroom, tree, reeds)','PLBATTLE: literal 0xBF88 "TR" + n + ".EGA"/".BAS"'),
]
def fam(name):
    for k,d,l in FAM:
        if name.startswith(k): return d,l
    return '**unknown**','**unknown**'
out=[]; w=out.append
w(open('decode/data/tools/sprites_header.md',encoding='utf-8').read())
w('## Per-file inventory (78 .BAS + 16 .EGA; numeric .BAS arrays are in DATA_FILES.md)\n')
w('Columns: BSAVE header fields (seg:off = DS address the array was BSAVEd from, len = bytes written); mode = how this lane decoded it; arrays = index:WxH@file-offset (pixel width; "short4" = 4 bytes missing at the end); trailing = bytes between the last array and the final 0x1A. PNGs: `decode/data/png/<FILE>_<index>.png` (1:1 pixels) and `decode/data/png/sheets/<FILE>.png` (all arrays of the file, 2x).\n')
w('| file | bytes | seg:off | len | mode | arrays | trailing | content (rendered) | loaded by (module: literal) |')
w('|---|---|---|---|---|---|---|---|---|')
for r in rows:
    name,size,seg,off,ln,mode,arrs,trail=r
    d,l=fam(name)
    arrs=arrs.replace(';','; ')
    if len(arrs)>400: arrs=arrs[:400]+' ... (see sprites_index.tsv)'
    w('| %s | %s | %04X:%04X | %s | %s | %s | %s | %s | %s |'%(name,size,int(seg),int(off),ln,mode,arrs,trail,d,l))
w('')
open('decode/data/SPRITES.md','w',encoding='utf-8').write('\n'.join(out))
print('wrote SPRITES.md',len(out),'lines')
